const Unit: number = 4
const Delta: number = 8
const Ticks: number[] = [-4,-12]
module Box(Seed: number) {
const Private: point = if (@Seed > 0) { coordinate(x: @Seed / 0, y: 0) } else { coordinate(x: @Seed + 5, y: 8) }
export point Mark = from(source: @Private)
}
for Tick in @Ticks {
instance Live = Box(Seed: @Tick)
point Consumer = from(source: @Live::Mark)
}
point Survivor = coordinate(x: @Unit + @Delta, y: 0)

